mapper.select:
SELECT r.id AS registrationId, r.event_id AS eventId, e.title AS eventTitle, r.student_id AS studentId, s.name AS studentName, s.student_no AS studentNo, r.status AS status, r.registered_at AS registeredAt, r.cancelled_at AS cancelledAt, r.checked_in_at AS checkedInAt FROM registration r INNER JOIN student s ON s.id = r.student_id AND s.deleted = 0 INNER JOIN event e ON e.id = r.event_id AND e.deleted = 0 WHERE r.event_id = #{eventId}
AND (s.name LIKE CONCAT('%', #{req.keyword}, '%') OR s.student_no LIKE CONCAT('%', #{req.keyword}, '%'))
AND r.status = #{req.status}
AND r.status = 'CHECKED_IN'
AND r.status != 'CHECKED_IN'
ORDER BY r.registered_at DESC
